// Signature verification on PDFs, and the PAN record parser. The fixtures are
// generated by scripts/make-signed-fixtures.ts and contain invented data.
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { ageOn, PanRecordError, parsePanRecord, pdfText } from "../lib/pan-record.ts";
import { certificateFingerprint, SignedPdfError, verifySignedPdf, type TrustedSigner } from "../lib/signed-pdf.ts";

const fixture = (name: string) => new Uint8Array(readFileSync(new URL(`./fixtures/signed/${name}`, import.meta.url)));
const TRUSTED: TrustedSigner[] = [
  { fingerprint256: certificateFingerprint(readFileSync(new URL("./fixtures/signed/trusted-signer.pem", import.meta.url), "utf8")), name: "Test issuer" },
];

const code = (f: () => unknown): string => {
  try {
    f();
  } catch (e) {
    if (e instanceof SignedPdfError) return e.code;
    throw e;
  }
  return "accepted";
};

describe("verifySignedPdf", () => {
  it("accepts a document signed by a trusted signer and reports the signing time", () => {
    const result = verifySignedPdf(fixture("pan-adult.pdf"), TRUSTED);
    expect(result.signer.name).toBe("Test issuer");
    expect(result.signedAt).toBeGreaterThan(1_700_000_000);
  });

  it("refuses a validly signed document from a signer that is not on the list", () => {
    expect(code(() => verifySignedPdf(fixture("pan-untrusted-signer.pdf"), TRUSTED))).toBe("signer_not_trusted");
    expect(code(() => verifySignedPdf(fixture("pan-adult.pdf"), []))).toBe("signer_not_trusted");
  });

  it("refuses a document with any signed byte changed", () => {
    const pdf = fixture("pan-adult.pdf");
    const text = Buffer.from(pdf).toString("latin1");
    // Change the year of birth in the page content, as a forger would.
    const at = text.indexOf("15-01-1990") + 6;
    expect(at).toBeGreaterThan(6);
    const forged = new Uint8Array(pdf);
    forged[at] = "2".charCodeAt(0);
    expect(code(() => verifySignedPdf(forged, TRUSTED))).toBe("signature_invalid");
  });

  it("refuses bytes appended after the signature", () => {
    const pdf = fixture("pan-adult.pdf");
    const extended = new Uint8Array(pdf.length + 64);
    extended.set(pdf);
    extended.fill(0x20, pdf.length);
    expect(code(() => verifySignedPdf(extended, TRUSTED))).toBe("signature_not_over_whole_file");
  });

  it("refuses a byte range that leaves part of the file uncovered", () => {
    const text = Buffer.from(fixture("pan-adult.pdf")).toString("latin1");
    const range = /\/ByteRange \[0 (\d{10}) (\d{10}) (\d{10})\]/.exec(text)!;
    const shorter = String(Number(range[3]) - 10).padStart(10, "0");
    const shrunk = new Uint8Array(Buffer.from(text.replace(range[0], `/ByteRange [0 ${range[1]} ${range[2]} ${shorter}]`), "latin1"));
    expect(code(() => verifySignedPdf(shrunk, TRUSTED))).toBe("signature_not_over_whole_file");
  });

  it("refuses a signature value from a different document", () => {
    const a = Buffer.from(fixture("pan-adult.pdf")).toString("latin1");
    const b = Buffer.from(fixture("pan-minor.pdf")).toString("latin1");
    const value = (s: string) => /\/Contents <([0-9a-f]+)>/.exec(s)![1]!;
    const swapped = new Uint8Array(Buffer.from(b.replace(value(b), value(a)), "latin1"));
    expect(code(() => verifySignedPdf(swapped, TRUSTED))).toBe("signature_invalid");
  });

  it("refuses an unsigned PDF and a file with two signatures", () => {
    const unsigned = new TextEncoder().encode("%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\n%%EOF\n");
    expect(code(() => verifySignedPdf(unsigned, TRUSTED))).toBe("not_signed");
    const pdf = fixture("pan-adult.pdf");
    const twice = new Uint8Array(pdf.length * 2);
    twice.set(pdf);
    twice.set(pdf, pdf.length);
    expect(code(() => verifySignedPdf(twice, TRUSTED))).toBe("multiple_signatures");
  });

  it("refuses a corrupted signature structure without crashing", () => {
    const text = Buffer.from(fixture("pan-adult.pdf")).toString("latin1");
    const garbage = new Uint8Array(Buffer.from(text.replace(/\/Contents <[0-9a-f]{8}/, "/Contents <ffffffff"), "latin1"));
    expect(code(() => verifySignedPdf(garbage, TRUSTED))).toBe("unsupported_signature");
  });
});

describe("PAN verification record", () => {
  it("reads the fields of a signed record", async () => {
    const record = parsePanRecord(await pdfText(fixture("pan-adult.pdf")));
    expect(record).toEqual({ pan: "ABCDE1234F", name: "ASHA EXAMPLE", dateOfBirth: { year: 1990, month: 1, day: 15 } });
  });

  it("refuses a signed document of another kind", async () => {
    const text = await pdfText(fixture("other-document.pdf"));
    expect(() => parsePanRecord(text)).toThrow(PanRecordError);
    expect(() => parsePanRecord(text)).toThrow("not_a_pan_record");
  });

  it("refuses a record with a missing or impossible date of birth", () => {
    const base = "PAN VERIFICATION RECORD Permanent Account Number ABCDE1234F NAME A B GENDER F";
    expect(() => parsePanRecord(base)).toThrow("unreadable_record");
    expect(() => parsePanRecord(`${base} DATE OF BIRTH 31-02-1990`)).toThrow("unreadable_record");
    expect(() => parsePanRecord(`${base} DATE OF BIRTH 15-13-1990`)).toThrow("unreadable_record");
  });

  it("computes age in completed years, turning 18 on the birthday itself", () => {
    const dob = { year: 2008, month: 10, day: 12 };
    const at = (iso: string) => Date.parse(iso) / 1000;
    expect(ageOn(dob, at("2026-10-11T23:59:59Z"))).toBe(17);
    expect(ageOn(dob, at("2026-10-12T00:00:00Z"))).toBe(18);
    expect(ageOn({ year: 2004, month: 2, day: 29 }, at("2022-02-28T12:00:00Z"))).toBe(17);
    expect(ageOn({ year: 2004, month: 2, day: 29 }, at("2022-03-01T00:00:00Z"))).toBe(18);
  });
});
